"""PFSA v2: ten explicit pages per domain; original case data remain unchanged."""
from pathlib import Path
import ast,json,html,shutil,zipfile,hashlib
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from pypdf import PdfReader

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT.parents[1]/'outputs'/'domain-guides-v2'
PUBLIC=ROOT/'public'/'guides'
OUT.mkdir(parents=True,exist_ok=True)
tree=ast.parse((ROOT/'scripts'/'build-domain-guides.py').read_text(encoding='utf-8'))
DATA=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='DATA' for t in n.targets))
READING=json.loads((ROOT/'lib'/'domain-reading.json').read_text())
DETAIL={
 'computer-cyber':dict(files='file_inventory.csv and activity.csv', question='What does the export support about changes to the report, and where does attribution remain uncertain?',tools='LibreOffice Calc and Writer; VS Code or another plain-text editor; Python 3 is optional for repeatable CSV checks. No disk imaging software is required for these exported tables.',example='Use record_id F1 and its activity reference as your first traceability example. A filename listed in a CSV is metadata, not a recovered document. The pack does not include original report contents.',checks=['Distinguish a filename, a version label and an actual file hash. Do not hash a CSV row and describe it as the hash of a missing report.','Compare event timestamps with the inventory timestamp and note that these are different fields with different meanings.','Check all file_record references against record_id. Explain whether a repeated version label represents independent source evidence.','Keep account labels such as service-B separate from a named human. A log label alone does not prove who operated the computer.'],lab='Open file_inventory.csv as text columns, then activity.csv in a separate worksheet. Count source rows, create an exact-key lookup on file_record, and retain unmatched rows. Export your joined worksheet as analysis.csv without overwriting either source. Select a single row and explain the full path from source row to conclusion.',pitfall='A modified timestamp is not automatically the time of a deliberate human edit. This pack cannot establish deletion, original disk state, malware presence or the contents of a missing report.',road='Evidence registration -> metadata comparison -> activity correlation -> supported case report'),
 'mobile':dict(files='device.json, messages.csv and app_events.csv',question='Which message and app events can be correlated, and what is absent from this logical teaching export?',tools='LibreOffice Calc and Writer; VS Code for device.json; a native SHA-256 utility. Python 3 is optional. A handset, USB cable, SIM card, paid extraction tool and Android Studio are not required.',example='Read device.json first. It states export type, timezone and missing evidence. Message IDs are not guaranteed to be unique: preserve every raw row and record your duplicate policy before deriving distinct-event counts.',checks=['Count physical rows and distinct message_id values separately. Preserve conflicting content even when identifiers repeat.','Treat message timestamps with +05:30 as offset-aware values. App events ending in Z are already UTC. Compare instants, not the displayed clock strings.','Separate an app entering the foreground from proof that a person read or authored a message. State which independent source would be needed.','Describe missing deleted content and incomplete OS history as limitations. Do not claim to recover anything that was not supplied.'],lab='Make a device summary from the JSON fields. Import messages.csv with message_id, timestamp and text held as text. Add row_number, duplicate_group and reason columns in a working copy. Convert 14:03:00+05:30 to 08:33:00Z as a separate practice example; verify each real row using its own time. Compare the UTC results to app_events.csv while retaining raw timestamps.',pitfall='Do not unlock, root, jailbreak or extract someone else\'s phone for this assignment. The required work is interpretation of PFSA synthetic exports, not bypassing a device or obtaining private messages.',road='Logical export scope -> message/app worksheet -> UTC event correlation -> mobile evidence report'),
 'network':dict(files='flows.csv and dns.csv',question='Which observed flow sequences deserve explanation, and what can metadata not establish?',tools='LibreOffice Calc and Writer are required. Wireshark is optional for reading its user guide and future authorised offline-PCAP work; the PFSA pack contains CSV flow/DNS exports, not a packet capture. Python 3 is optional.',example='Use flow_id as the flow reference and event_id as the DNS reference. The synthetic IP addresses use documentation ranges. A shared response IP is not a unique link between one DNS event and one flow.',checks=['Define bytes, source address, destination address, destination port and time before using them. A destination port is not proof of the application used.','Calculate grouped counts and byte totals on the working copy. Label the sample as a small training dataset, not a normal baseline for a real enterprise.','Choose a documented time window for DNS matching; retain ambiguous matches, different client addresses and unmatched flows.','Compare an ordinary backup explanation with an unverified transfer explanation. Large byte counts alone do not establish exfiltration.'],lab='Import both CSVs with IP addresses and identifiers preserved as text. Create a pivot table grouped by src, dst and dst_port with count(flow_id) and sum(bytes). Save the pivot settings or describe them exactly. For one flow, list every DNS record within your chosen window and explain which client field agrees or conflicts.',pitfall='Wireshark does not turn a flow CSV into the original packets. There is no live sniffing, scanning, interception or traffic decryption task in this pack.',road='Network map -> grouped flow observations -> DNS/flow chronology -> defensible network report'),
 'cloud':dict(files='audit.jsonl and assets.csv',question='What do the audit events show about principal actions and object access, and what provider evidence is missing?',tools='VS Code or another plain-text editor for JSONL; LibreOffice Calc and Writer; optional Python 3 with its standard json and csv modules. No AWS, Azure or Google Cloud account, payment card or API key is needed.',example='Each line of audit.jsonl is a separate JSON object, not one giant JSON array. Use event_id as the stable evidence reference. Keep result=denied distinct from success when counting object actions.',checks=['Identify the fictional tenant, principal labels and asset scope before interpreting actions. A principal label is not a verified person.','Classify event actions using the exact strings in the file; retain unexpected values rather than silently dropping them.','Count denied attempts separately from successful reads. A read event does not reveal the object contents or prove a later transfer.','Configuration-change events require before/after state and relevant permissions context to judge impact. Record these as evidence gaps.'],lab='Open audit.jsonl in the editor and inspect one complete line without reformatting the original. Copy to working, then use Python json.loads(line) for each non-empty line or manually create a small tabular worksheet. Validate event_id, timestamp, principal, action, target and result. Compare targets with assets.csv and retain targets that do not match the inventory exactly.',pitfall='Do not create live tenant credentials or collect another organisation\'s audit logs. A training log export cannot establish a complete provider-side history or geographical location of a person.',road='Tenant and export scope -> identity/action matrix -> object-access timeline -> cloud forensic handover'),
 'database':dict(files='training.db and schema.sql',question='Are the final ledger rows internally consistent with their keys, arithmetic and audit transitions?',tools='DB Browser for SQLite with Open Database Read Only; LibreOffice Calc and Writer; plain-text editor. Python 3 sqlite3 is an optional alternative. PostgreSQL reading is background only; do not migrate this SQLite evidence file into a new database for the core task.',example='The fixture contains customers, orders and audit tables. Record the schema as supplied. A customer reference with no matching customer and a total that differs from quantity times unit_price are observations, not automatic evidence of wrongdoing.',checks=['Open a working copy read-only and record that mode. Do not click Write Changes or run an UPDATE, DELETE, VACUUM or repair operation on the evidence.','Preserve exact SELECT statements beside results. If a tool reformats values, record the display format and compare numeric values explicitly.','Use a LEFT JOIN to retain orders whose customer is missing. An INNER JOIN would silently remove those rows from the result.','Link audit.order_id to orders.id and compare transition values in time order. An application audit trail is not a full transaction log.'],lab='Open the working database with the read-only command. In Execute SQL, run SELECT name FROM sqlite_master WHERE type=\'table\'; then SELECT COUNT(*) FROM orders;. Save query text to checks.sql and results to CSV. For the discrepancy check, use SELECT id, quantity*unit_price AS expected_total, total FROM orders WHERE total != quantity*unit_price;. Include the schema and note how currency precision would be handled in a real ledger.',pitfall='A clean integrity check does not prove the business data are correct. Do not treat the supplied audit actor as a verified person or infer deleted rows without suitable evidence.',road='Read-only intake -> relational/arithmetic checks -> audit reconstruction -> database findings report'),
 'iot':dict(files='devices.csv, telemetry.csv and gateway.csv',question='How do device clock assumptions and telemetry quality affect the gateway chronology?',tools='LibreOffice Calc and Writer; plain-text editor; optional Python 3 for grouping and timestamps. No sensor board, soldering kit, radio adaptor, firmware tool or cloud subscription is required.',example='devices.csv supplies gateway relationships, measurement units and clock_offset_seconds. State whether your chosen offset convention means the device clock is ahead of UTC. Preserve the original time even when calculating an adjusted value.',checks=['Group readings by device before checking sequence values. A repeated sequence across different devices is not necessarily a duplicate.','Calculate reading count, min/max and consecutive time gaps separately. Do not insert invented readings into the original evidence to fill gaps.','Create adjusted_utc in a new column. For an assumed clock that is 120 seconds ahead, subtract 120 seconds; explain why that convention was selected.','Compare gateway disconnect/reconnect events with telemetry gaps using a documented tolerance. A timing association alone is not proof of physical tampering.'],lab='Import devices.csv and create a device-to-gateway map with each clock offset and unit. Join metadata to a working telemetry table by device_id while retaining unknown devices. Calculate gaps between consecutive readings of the same device. Compare raw and adjusted timelines to gateway.csv and mark any conclusion that changes when the offset assumption changes.',pitfall='This exercise does not include physical acquisition, firmware history or a live sensor. A reconnect or missing sample cannot by itself prove that someone interfered with a device.',road='Device ecosystem map -> telemetry quality review -> clock-aware correlation -> IoT case report')
}

NAVY=colors.HexColor('#13243d');GOLD=colors.HexColor('#ad8137');MUTED=colors.HexColor('#526278')
styles=getSampleStyleSheet()
for name,size,leading,color in [('Title2',23,28,NAVY),('Head2',13,17,GOLD),('Body2',10,14.4,NAVY),('Small2',8.4,11.8,MUTED)]:
 styles.add(ParagraphStyle(name=name,fontName='Helvetica-Bold' if name in ('Title2','Head2') else 'Helvetica',fontSize=size,leading=leading,textColor=color,spaceAfter=9))

def P(text,style='Body2'):
 return Paragraph(html.escape(text).replace('\n','<br/>'),styles[style])
def heading(text):return P(text,'Head2')
def link(title,url):
 return Paragraph('<a color="#8b6327" href="'+html.escape(url,quote=True)+'">'+html.escape(title)+'</a>',styles['Small2'])
def bullets(items,start=1):return [P(f'{i}. {t}') for i,t in enumerate(items,start)]
def table(rows,widths):
 t=Table([[P(str(c),'Small2') for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf1f6')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#dce2eb')),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),5)]));return t

def chrome(title):
 def draw(c,doc):
  c.drawImage(str(ROOT/'public/assets/documents/guide-logo.jpeg'),42,775,width=47,height=47,preserveAspectRatio=True,mask='auto')
  c.setFillColor(NAVY);c.setFont('Helvetica-Bold',10);c.drawString(102,807,'PRAMAAN FORENSICS ACADEMY')
  c.setFont('Helvetica',8);c.setFillColor(MUTED);c.drawString(102,791,title)
  c.setStrokeColor(GOLD);c.setLineWidth(.8);c.line(42,769,553,769)
  c.line(42,43,553,43);c.setFont('Helvetica',7.5);c.setFillColor(MUTED)
  c.drawString(42,28,'PFSA | Detailed task guide v2.0 | 13 November 2026')
  c.drawRightString(553,28,f'{doc.page:02d} / 10')
 return draw

def page(title,subtitle,content):return [P(subtitle.upper(),'Small2'),P(title,'Title2'),*content,PageBreak()]

manifest=[];checks=[]
for key,(title,scenario,weeks) in DATA.items():
 d=DETAIL[key];story=[]
 # Pages 1-5: tasks come before requirements, as requested.
 overview=[P(scenario),heading('The investigation question'),P(d['question']),heading('Your four weekly tasks')]
 for i,(name,steps,deliverables) in enumerate(weeks,1):overview += [heading(f'Week {i} | {name}'),P(' '.join(steps[:2]),'Small2'),P('Output: '+deliverables,'Small2')]
 overview += [P('Read pages 2-5 for the full checklists. Submission rules follow on page 6; requirements and installation are on pages 7-8. Worked methods and three reading downloads are on page 9. The complete roadmap is the final page.','Small2')]
 story+=page('Weekly task list',title,overview)
 for number,(name,steps,deliverables) in enumerate(weeks,1):
  activities=[heading('Objective'),P(['Create a trustworthy baseline before interpreting any record.','Turn source records into a documented examination worksheet.','Correlate events without hiding uncertainty or alternative explanations.','Deliver a clear, reproducible report that answers the case question.'][number-1]),heading('Do this in order')]
  activities+=bullets(steps)
  activities+=bullets([
   [f'Create a case note naming {d["files"]}. For each, record evidence ID, original filename, byte size, SHA-256 and where the PFSA ZIP was downloaded. Keep the supplied manifest with the ZIP.', 'Open the preserved copy only to verify integrity. Use working copies for tables, sorting and annotations. Record source row counts so later filters can be checked.',d['checks'][0]][0] if number==1 else
   [f'Keep all original columns from {d["files"]}. Add new analysis columns rather than replacing source identifiers or timestamps. Preserve the query, formula or filter used.',d['checks'][1]][0] if number==2 else
   'Give every derived timeline event an exact source file and row or event ID. Record raw time, UTC time, conversion rule, evidence meaning and uncertainty in separate fields.' if number==3 else
   'Write an executive summary first, then scope, evidence register, tool versions, reproducible methods, findings, alternatives, limitations and conclusion. Put detailed tables and queries in appendices.',
   d['checks'][number-1],
   'Recheck one result independently: return to the source, repeat the calculation or lookup, and record whether it agrees. Keep a short correction log instead of silently revising previous findings.'
  ],start=4)
  activities += [heading('Required hand-in'),P(deliverables),P(f'Name the upload PFSA_<student-id>_{key}_W{number}.pdf or .zip. A ZIP may contain the report plus CSV, SQL, images or other permitted supporting work. Do not rename a non-PDF file to .pdf. Keep the one portal upload below 10 MB.','Small2'),heading('Portal description and acceptance check'),P('Write at least 200 genuine words in the description box: what you examined, how you processed it, exact evidence references, results, uncertainty and what you learned. Before submitting, open the uploaded work locally, confirm all filenames resolve, and compare original-file hashes with your intake record.','Small2')]
  story+=page(name,f'Week {number} | task instructions',activities)
 # Page 6: exact hand-in and grading requirements.
 story+=page('Submission & assessment','After the weekly task list',[
  heading('What to submit each week'),P('Submit one main project file and a separate portal narrative of at least 200 words. Use a PDF for a readable report; use a ZIP when the report needs supporting CSV, SQL, JSON, screenshots or source code. The portal supports multiple work formats, but it is not a substitute for organising your evidence.'),
  table([['Item','Required content'],['Main report','Student ID, domain, week, case question, scope, method, findings and limitations.'],['Appendices','Source references, derived tables, saved formulas/queries, tool versions and relevant screenshots.'],['Integrity record','Original file hashes and verification result; explain whether any working file changed.'],['Portal narrative','At least 200 words written in your own words; a report attachment does not replace this field.']],[105,406]),Spacer(1,14),
  heading('A useful 200-word narrative structure'),P('Use approximately 40-60 words for scope and inputs, 60-90 for your actual method, 60-90 for supported findings, and 40-60 for uncertainty and learning. These are writing prompts, not text to copy. Mention at least two precise record references and one limit of the evidence. Do not repeat a sentence or paste filler just to reach the counter.'),
  heading('Marking rubric | 100 marks per week'),table([['Criterion','Marks','What a reviewer looks for'],['Integrity and scope','20','Correct baseline, preserved originals and a defined question.'],['Method','25','Reproducible steps, versions, calculations and saved filters.'],['Analysis','25','Supported reasoning and alternatives, with appropriate uncertainty.'],['Evidence references','20','Exact file and row/event references for each significant finding.'],['Communication','10','Clear report, organised package and meaningful portal description.']],[128,46,337]),Spacer(1,12),
  P('Calendar deadlines and any resubmission instructions are published in the portal by staff. Four submissions unlock the next document stage; payment confirmation, project assessment and document publication remain staff-controlled. Ask Support about an incorrect upload or locked record.','Small2')])
 # Page 7: equipment and software, after all task/submission details.
 story+=page('Requirements before you begin','Laptop, software & files',[
  heading('Laptop and workspace'),P('Use a laptop or desktop with a supported Windows, macOS or Linux installation, a keyboard and permission to install the required applications. For these small training exports, 4 GB RAM is a practical minimum; 8 GB is recommended. Reserve at least 2 GB free for tools and working files, with additional space for downloaded books. A phone can read PDFs and check portal status, but a laptop is strongly recommended for evidence tables, file packaging and reproducible work.'),
  heading('Required software for this domain'),P(d['tools']),
  heading('Common tools and their purpose'),table([['Tool','Use in the assignment'],['LibreOffice Calc','Import CSVs, retain text identifiers, calculate summaries and save derived tables.'],['LibreOffice Writer','Write the case report and export it as a readable PDF.'],['Plain-text editor / VS Code','Inspect JSON, JSONL, SQL and notes without altering formatting in a word processor.'],['Native SHA-256 utility','Create and compare an integrity baseline for each source file.'],['Browser and PDF reader','Read the guide, open references and submit work through the student portal.']],[140,371]),Spacer(1,14),
  heading('Training files and folder structure'),P(f'Download {key}-training-data.zip from the matching domain card. Its central source files are {d["files"]}. Save the original ZIP, extract it once, and create four folders: originals, working, analysis and submission. Put the original extracted files in originals, analysis copies in working, derived outputs in analysis, and only final hand-in material in submission.'),
  heading('Before the first task'),P('Record your operating system and the installed application versions. Confirm that the file extensions are visible and that you can create a CSV, open a PDF and make a ZIP. Avoid syncing personal or confidential data into this case folder. The training pack is fictional; no purchase, live investigation account or collection from another person is needed.','Small2')])
 # Page 8: installation details, based on primary vendor instructions.
 setup=[heading('1 | Install a document and spreadsheet suite'),P('Open the official LibreOffice download page and choose your operating system and CPU architecture. On Windows, download the stable main installer, run it and follow the standard setup prompts; open both Calc and Writer after installation. On macOS, choose Intel or Apple Silicon as appropriate, open the DMG and move LibreOffice to Applications. On Linux, prefer the distribution\'s supported software manager. Record the version in your case notes.'),link('LibreOffice download and installation instructions','https://www.libreoffice.org/installation-instructions/'),
  heading('2 | Set up a plain-text editor'),P('Download VS Code from its official site if you do not already have a suitable editor. On Windows, the user installer normally avoids a machine-wide installation. Open only your working case folder using File > Open Folder. Inspect JSON or SQL as text, keep automatic file formatting off for evidence copies, and do not add extensions that are not needed. A built-in text editor is sufficient when installing VS Code is not possible.'),link('Official VS Code Windows setup','https://code.visualstudio.com/docs/setup/windows'),
  heading('3 | Verify hashes without an extra package'),P('On Windows, open PowerShell in your working case folder and run Get-FileHash -Algorithm SHA256 .\\originals\\<filename>. On macOS use shasum -a 256 originals/<filename>. On Linux use sha256sum originals/<filename>. Replace the placeholder with one actual filename. Save each digest with its filename, size, date and tool. Repeating the command against the same preserved file should produce the same digest.'),
  heading('4 | Domain-specific installation and first run')]
 if key=='database':setup += [P('Download the stable DB Browser for SQLite build for your operating system from the official site. Install or extract it, launch it and use Open Database Read Only to select working/training.db. Check the title/status for read-only mode before examining tables. If that mode is unavailable, use a new working copy and the documented Python alternative with URI mode=ro; do not use a production database.'),link('DB Browser official downloads','https://sqlitebrowser.org/dl/')]
 elif key=='network':setup += [P('Wireshark is optional because the supplied work uses CSVs. If you install it, use the stable build from the official download page and follow the matching operating-system instructions. A packet-capture driver is unnecessary for this CSV assignment. Open the user guide; do not start a live capture. Ask staff for an authorised offline PCAP before attempting packet-level practice.'),link('Wireshark official downloads and user guide','https://www.wireshark.org/download.html')]
 else:setup += [P('Python 3 is optional for repeatable checks. Use the official Python download page, select a supported stable Python 3 distribution and follow its operating-system instructions. Open a new terminal and verify python --version, python3 --version or py --version as appropriate. Standard csv, json, hashlib, datetime and sqlite3 modules are enough for these labs; third-party packages are not required.'),link('Python official downloads','https://www.python.org/downloads/')]
 setup += [P('Installation checks: create a test worksheet, export one PDF, read one source file from a working copy and reproduce a SHA-256 digest. Save a short tools.txt with versions and any differences from these instructions. Official setup pages are the source of truth if a vendor changes a screen label.','Small2')]
 story+=page('Installation & first-run checks','Practical setup | Windows, macOS & Linux',setup)
 # Page 9: domain first-run example and three attributed downloads.
 reading=[heading('First reproducible examination'),P(d['lab']),heading('A limit you must state'),P(d['pitfall']),heading('Three books & substantial reference downloads'),P('Use the original publisher or author links below. Reference guides and manuals are labelled separately from textbooks. Older editions provide background; they are not a substitute for current tool documentation. Third-party authors retain their rights and do not endorse PFSA.','Small2')]
 for i,r in enumerate(READING[key],1):
  reading += [heading(f'{i} | {r["title"]}'),P(f'{r["author"]} | {r["edition"]} | {r["kind"]}','Small2'),P(r['use'],'Small2'),link('Open authorised PDF / author download page',r['url'])]
 reading += [P('Download links checked 13 November 2026. Use the source page if a PDF host changes or restricts automated downloads. '+('Foundations of Databases is linked to the authors download page because its personal-use terms prohibit redistribution. ' if key=='database' else '')+'These reading files are not required attachments to your weekly submission.','Small2')]
 story+=page('Worked method & reading library','Domain-specific guidance',reading)
 # Page 10 is always the roadmap, never a bibliography or generic back cover.
 roadmap=[heading('Your four-stage learning path'),P(d['road']),P('Use this roadmap to plan the sequence, not to calculate calendar deadlines. Staff publish the actual dates in your portal. Early Start changes when access opens; it does not remove any weekly deliverable or assessment requirement.'),
  table([['Stage','Suggested focus','Checkpoint before moving on'],['Week 1 | Preserve','Days 1-2: scope and inventory. Days 3-4: integrity and working copy. Days 5-7: review and submission.','Every source has an ID, hash and documented limitation.'],['Week 2 | Examine','Days 8-9: field definitions. Days 10-11: structured checks. Days 12-14: independent recheck and submission.','Derived tables retain original IDs and reproducible calculations.'],['Week 3 | Correlate','Days 15-16: time conversion. Days 17-18: source correlation. Days 19-21: alternatives and submission.','Timeline retains raw time and explains ambiguity, not just a neat order.'],['Week 4 | Communicate','Days 22-23: findings. Days 24-25: report and appendices. Days 26-28: independent review and final hand-in.','A reviewer can repeat the method and trace every significant claim.']],[105,231,175]),Spacer(1,18),
  heading('Daily working habit'),P('Start by reading your last case note and checking the source hash. Work on one defined question, save the method and result, then write a brief end-of-session note: completed work, decisions, outstanding questions and next step. Keep the final report consistent with the latest version of the analysis tables.'),
  heading('Final readiness gate'),P('Confirm four genuine weekly submissions, complete evidence references, original-file integrity checks and an organised final report. Read staff feedback and resolve requested corrections. Keep a personal copy of the submitted package and the portal acknowledgement. Document eligibility and recommendation remain subject to assessment and the academy\'s published service terms.'),
  heading('What you should be able to demonstrate'),P('Explain the supplied evidence boundary, reproduce one key finding, compare a competing explanation and describe which additional evidence would improve confidence. That explanation is more valuable than a screenshot of a tool running.'),link('Student portal and Support','https://prammanforensics.in/student')]
 story+=page('Four-week learning roadmap','Final page | plan, practise, verify',roadmap)
 story.pop() # no trailing blank page
 path=PUBLIC/f'{key}-task-guide.pdf'
 SimpleDocTemplate(str(path),pagesize=(595.28,841.89),leftMargin=46,rightMargin=46,topMargin=90,bottomMargin=58,title=f'{title} - Detailed Tasks and Roadmap',author='Pramaan Forensics Academy').build(story,onFirstPage=chrome(title),onLaterPages=chrome(title))
 reader=PdfReader(path)
 assert len(reader.pages)==10,(key,len(reader.pages))
 assert 'Weekly task list' in reader.pages[0].extract_text()
 assert 'Four-week learning roadmap' in reader.pages[-1].extract_text()
 assert all(len(p.images)>=1 for p in reader.pages),(key,'missing logo')
 assert all(len(p.extract_text())>900 for p in reader.pages),(key,'thin page')
 shutil.copy2(path,OUT/path.name)
 checks.append({'domain':key,'pages':10,'words':sum(len(p.extract_text().split()) for p in reader.pages),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
 manifest.append({'programme':key,'title':title,'url':f'/guides/{key}-task-guide.pdf','dataset':f'/guides/{key}-training-data.zip','pages':10,'version':'2.0','weeks':[{'week':i,'title':w[0],'description':' '.join(w[1]),'deliverables':w[2]} for i,w in enumerate(weeks,1)]})
(ROOT/'lib/domain-guides.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
(OUT/'validation.json').write_text(json.dumps(checks,indent=2))
with zipfile.ZipFile(OUT/'PFSA-All-Six-Domain-Guides.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in OUT.glob('*-task-guide.pdf'):z.write(p,p.name)
 z.write(ROOT/'lib/domain-reading.json','18-reading-download-links.json')
print(json.dumps(checks,indent=2))
